-- ── IT-JE-18 ─────────────────────────────────────────────────────
INSERT INTO document_content (
  document_id, objetivo, alcance,
  definiciones, responsabilidades, material_equipo, desarrollo,
  gestion_riesgos, referencias, control_cambios,
  elaborado_por, cargo_elaboro,
  revisado_por,  cargo_reviso,
  autorizado_por, cargo_autorizo
)
SELECT d.id,
'Inicia con el cumplimiento del código de vestimenta para el ingreso al área de hemodiálisis, finaliza con el desecho de material contaminado.',
'Inicia con el cumplimiento del código de vestimenta para el ingreso al área de hemodiálisis, finaliza con el desecho de material contaminado.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "Uniforme quirúrgico"}, {"item": "Gorro desechable"}, {"item": "Cubrebocas"}, {"item": "Bata desechable"}, {"item": "Bata de traslado"}, {"item": "Lente o careta de protección"}, {"item": "Guante crudo"}, {"item": "Tánico para ropa sucia"}, {"item": "Bote para basura común"}, {"item": "Bote con bolsa roja RPBI"}]'::jsonb,
'[{"no": "5.1", "responsable": "Enfermería", "actividad": "Cumple con el código de vestimenta. Retirar accesorio (Cadenas, anillos, aretes, pulseras, reloj, etc.). Deja sus pertenencias en locker e ingresa al área de hemodiálisis solo su uniforme y material necesario para su labor."}, {"no": "5.1b", "responsable": "Supervisión", "actividad": "Verifica el uso correcto del equipo de protección personal, así como de su clasificación y desecho correcto."}, {"no": "5.2", "responsable": "Enfermería", "actividad": "Ingresa al área de hemodiálisis colocándose gorro desechable, cubre bocas y bata para pasar al vestidor y realizar el cambio de uniforme clínico por quirúrgico, resguarda el uniforme clínico en el lugar designado."}, {"no": "5.2b", "responsable": "Enfermería", "actividad": "Realiza higiene de manos IT-UV-01 Higiene de manos con agua y jabón."}, {"no": "5.3", "responsable": "Enfermería", "actividad": "Antes de entrar en contacto con el paciente, su entorno o manejar el equipo e insumos, realiza lavado de manos clínico. IT-UV-01 Higiene de manos con agua y jabón."}, {"no": "5.4", "responsable": "Enfermería", "actividad": "Respeta los 5 momentos para la higiene de manos."}, {"no": "5.4b", "responsable": "Enfermería", "actividad": "Programa, en medida de lo posible, sesiones de pacientes infectocontagiosos en horario que no coincida con pacientes sin patología infecto contagiosa."}, {"no": "5.5", "responsable": "Enfermería", "actividad": "En paciente con serología positiva sigue IT-JE-19 instrucción de trabajo para la atención y manejo de usuario con serología positiva en hemodiálisis."}, {"no": "5.6", "responsable": "Enfermería", "actividad": "Coloca equipo de protección adicional previo al ingreso del paciente, acorde a la medida precautoria que requiera. PR-UV-15 Procedimiento de medidas de prevención estándar."}, {"no": "5.7", "responsable": "Enfermería", "actividad": "Al termino de sesión de paciente considerado infecto contagioso se retira el equipo de protección desechable y dispone de él considerando la clasificación y desecho de RPBI. PR-JE-08 Manejo de Residuos Peligrosos Biológico Infecciosos. Desecha la ropa acorde a IT-JE-27 Retiro y clasificación de ropa sucia o contaminada."}, {"no": "5.8", "responsable": "Enfermería", "actividad": "Al salir del área en caso de urgencia, se coloca bata clínica o quirúrgica de traslado, cerrada en su totalidad y resguarda gorro desechable."}, {"no": "5.9", "responsable": "Enfermería", "actividad": "Si en el cumplimiento de sus deberes, el uniforme del colaborador sufre algún derrame de fluidos, deberá solicitar al departamento de quirófano un uniforme quirúrgico de la empresa y realizar el cambio."}, {"no": "5.10", "responsable": "Enfermería", "actividad": "Realiza el cambio de uniforme quirúrgico por clínico al salir del área."}, {"no": "5.13", "responsable": "Enfermería", "actividad": "Al finalizar el turno, antes de retirarse del área, debe desechar el equipo de protección que utilizo durante el desarrollo de sus labores según corresponda, a basura común o RPBI y realizar higiene de manos IT-UV-01 Higiene de manos con agua y jabón."}]'::jsonb,
'[{"riesgo": "Transmisión de microorganismos patógenos por incumplimiento en las medidas precautorias.", "barrera": "Uso del equipo de protección adecuado a la medida precautoria. Realizar higiene de manos respetando los 5 momentos."}, {"riesgo": "Riesgo de infección por incumplimiento en serologías.", "barrera": "Informar de manera clara los requisitos pre hemodiálisis. Revisar serologías en nuevos pacientes. Pedir renovación de serologías en pacientes frecuentes."}]'::jsonb,
'[{"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}, {"nombre": "Procedimiento de medidas de prevención estándar", "codigo": "PR-UV-15"}, {"nombre": "Retiro y clasificación de ropa sucia o contaminada", "codigo": "IT-JE-27"}, {"nombre": "Proceso para el manejo de Residuos Peligrosos Biológico Infecciosos", "codigo": "PR-JE-08"}, {"nombre": "Instrucción de trabajo para la atención y manejo de usuario con serología positiva en hemodiálisis", "codigo": "IT-JE-19"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
FROM documents d WHERE d.code = 'IT-JE-18'
