SELECT d.id,
'Inicia con la programación de la sesión en el área de hemodiálisis y finaliza con el cierre de registros de enfermería.',
'Inicia con la programación de la sesión en el área de hemodiálisis y finaliza con el cierre de registros de enfermería.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "Uniforme quirúrgico"}, {"item": "Gorro desechable"}, {"item": "Cubre boca"}, {"item": "Bata quirúrgica"}, {"item": "Lente o careta de protección"}, {"item": "Guante estéril"}, {"item": "Guante crudo"}, {"item": "Bolsa roja de RPBI"}, {"item": "Bote rígido para punzocortante"}, {"item": "Dilución de cloro al 1% y franela verde para reposet o camilla"}, {"item": "Surfa safe y franela morada para equipo"}]'::jsonb,
'[{"no": "5.1", "responsable": "Enfermería", "actividad": "Al tener programada sesión de hemodiálisis para paciente con serología positiva, verifica que el procedimiento a seguir sea el correcto. IT-JE-39 Admisión, ingreso y egreso del usuario hospitalizado a la unidad de hemodiálisis. IT-JE-40 Admisión, ingreso y egreso del usuario externo a la unidad de hemodiálisis."}, {"no": "5.2", "responsable": "Enfermería", "actividad": "Programa sesión en un turno distinto al resto de usuarios con serología negativa, o bien, se podrá realizar en conjunto con otros pacientes con serología positiva. De no ser posible se realizará en conjunto con pacientes con serología negativa solo con autorización médica, solicitando biombo de división para el equipo contiguo."}, {"no": "5.3", "responsable": "Enfermería", "actividad": "Realiza, previo al inicio de actividades IT-UV-01 Higiene de manos con agua y jabón."}, {"no": "5.4", "responsable": "Enfermería", "actividad": "Porta adecuadamente las medidas precautorias para el manejo del usuario con serología positiva. IT-JE-18 Manejo de medidas precautorias para el personal de hemodiálisis."}, {"no": "5.5", "responsable": "Enfermería", "actividad": "Identifica al paciente a su ingreso PR-JE-01 MISP 1. Identificación correcta del paciente, lo pesa e instala en la unidad asignada, y realiza monitoreo."}, {"no": "5.6", "responsable": "Enfermería", "actividad": "Procede al inicio del tratamiento hemodiálisis IT-JE-26 Intervención de enfermería en el tratamiento de hemodiálisis. De ser posible da la atención exclusiva como medida preventiva de contagio, mientras este se encuentre en tratamiento, haciendo en todo momento el uso correcto del equipo de protección y respetando los 5 momentos para la higiene de manos."}, {"no": "5.7", "responsable": "Enfermería", "actividad": "Realiza la asepsia del acceso vascular, y se procede con la conexión de las líneas o punción según sea el caso. Y se realiza valoración constante durante el procedimiento. IT-JE-20 Manejo y cuidado de acceso vascular para hemodialisis – cateter. IT-JE-21 El manejo y cuidado del acceso vascular para hemodialisis – FAVI."}, {"no": "5.8", "responsable": "Enfermería", "actividad": "Mantiene informado a médico tratante en caso de cualquier alteración hemodinámica del paciente. PR-JE-02 MISP 2 Comunicación efectiva."}, {"no": "5.9", "responsable": "Enfermería", "actividad": "Realiza limpieza inmediata de salpicaduras de sangre o secreciones."}, {"no": "5.10", "responsable": "Enfermería", "actividad": "Realiza retorno sanguíneo con circuito cerrado sin excepción, desechar sobrantes de solución acida y bicarbonato, así mismo material sobrante que estuviera en contacto con la mesa de trabajo usada con el usuario. PR-JE-08 Manejo de RPBI."}, {"no": "5.11", "responsable": "Enfermería", "actividad": "Utiliza guantes crudos para el retiro de equipos, cerrar clamps y colocar tapones, evitando derrames."}, {"no": "5.12", "responsable": "Enfermería", "actividad": "Desecha como RPBI todo material desechable, aunque no estén impregnados de sangre. PR-JE-08 Manejo de RPBI."}, {"no": "5.13", "responsable": "Enfermería", "actividad": "Valora estado de paciente, si está en condiciones, realiza su egreso. En caso de requerir ayuda, avisa a servicio de camillería."}, {"no": "5.14", "responsable": "Enfermería", "actividad": "Realiza la limpieza y desinfección profunda de toda superficie en contacto con sangre, siempre usando guante crudo. IT-JE-22 Técnica de desinfección de la máquina de hemodiálisis."}, {"no": "5.15", "responsable": "Enfermería", "actividad": "Desecha todo material utilizado con el usuario en bolsa roja y la cierra al término de la sesión."}, {"no": "5.16", "responsable": "Enfermería", "actividad": "Retira equipo de protección, desechando como RPBI lo desechable PR-JE-08 Manejo de RPBI. La ropa de reuso la desecha en bolsa transparente y la rotula IT-JE-27 Retiro y clasificación de ropa sucia o contaminada. En caso de uso de goggles, los desinfecta y resguarda en su lugar."}, {"no": "5.17", "responsable": "Enfermería", "actividad": "Realiza el reporte de enfermería, y las anotaciones pertinentes de acuerdo a hoja de enfermería en hemodiálisis."}]'::jsonb,
'[{"riesgo": "Riesgo de contagio por mal manejo de fluidos.", "barrera": "Uso de equipo de protección en todo momento. Realizar higiene de manos con agua y jabón. Desinfección oportuna posterior al derrame de fluidos."}, {"riesgo": "Omisión en la aplicación de las medidas de seguridad de manera eficiente.", "barrera": "Identificar las medidas precautorias que apliquen. Respetar el equipo de protección correspondiente."}, {"riesgo": "Desinfección inadecuada de superficies y equipo.", "barrera": "Apego secuencial a los pasos de limpieza y desinfección de superficies contaminadas."}]'::jsonb,
'[{"nombre": "Guía sobre enfermedades víricas en hemodiálisis 2004, NEFROLOGÍA Vol. XXIV (2004)", "codigo": "No aplica"}, {"nombre": "Manejo de medidas precautorias para el personal de hemodiálisis", "codigo": "IT-JE-18"}, {"nombre": "Manejo y cuidado de acceso vascular para hemodialisis – cateter", "codigo": "IT-JE-20"}, {"nombre": "El manejo y cuidado del acceso vascular para hemodialisis – FAVI", "codigo": "IT-JE-21"}, {"nombre": "Técnica de desinfección de la máquina de hemodiálisis", "codigo": "IT-JE-22"}, {"nombre": "Intervención de enfermería en el tratamiento de hemodiálisis", "codigo": "IT-JE-26"}, {"nombre": "Retiro y clasificación de ropa sucia o contaminada", "codigo": "IT-JE-27"}, {"nombre": "Admisión, ingreso y egreso del usuario hospitalizado a la unidad de hemodiálisis", "codigo": "IT-JE-39"}, {"nombre": "Admisión, ingreso y egreso del usuario externo a la unidad de hemodiálisis", "codigo": "IT-JE-40"}, {"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}, {"nombre": "MISP 1 Identificación correcta del paciente", "codigo": "PR-JE-01"}, {"nombre": "MISP 2 Comunicación efectiva", "codigo": "PR-JE-02"}, {"nombre": "Manejo de RPBI", "codigo": "PR-JE-08"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
FROM documents d WHERE d.code = 'IT-JE-19'
