SELECT d.id,
'Inicia aplicando las medidas precautorias y realizando higiene de manos, finaliza con la desinstalación del equipo de la máquina de hemodiálisis.',
'Inicia aplicando las medidas precautorias y realizando higiene de manos, finaliza con la desinstalación del equipo de la máquina de hemodiálisis.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "Mesa de trabajo"}, {"item": "Guante estéril (2 pares) - conexión"}, {"item": "Campo estéril desechable - conexión"}, {"item": "Jeringa 3 ml (2pzas) - conexión"}, {"item": "Gasa de 7.5 cm x 5cm (9 pzas) - conexión"}, {"item": "Apósito hypafix estéril - conexión"}, {"item": "Gasa de 20cm x 10cm (1pza) - desconexión"}, {"item": "Gasa de 7.5cm x 5cm (4pzas) - desconexión"}, {"item": "Tapón de rosca estéril desechable (2 pzas) - desconexión"}, {"item": "Guante estéril (2 pares) - desconexión"}, {"item": "Paquete gasa mediana estéril 10cm x 10cm"}, {"item": "Jeringa 20 ml (2pzas)"}, {"item": "Jeringas 10ml (2pzas)"}, {"item": "Jeringa 5ml (2pzas)"}, {"item": "Cinta adherible micropore"}, {"item": "Alcohol isopropilico 70%"}, {"item": "Microdacyn"}, {"item": "Guantes crudos (4 pzas)"}, {"item": "Heparina 5000 UI/10ML Fco"}]'::jsonb,
'[{"no": "5.1", "responsable": "Enfermería", "actividad": "Realiza IT-UV-01 Higiene de manos con agua y jabón, y realiza IT-JE-18 Manejo de medidas precautorias para el personal de hemodiálisis."}, {"no": "5.2", "responsable": "Enfermería", "actividad": "Instala al paciente en camilla o reposet asignado y realiza monitoreo de constantes vitales. IT-JE-39 Admisión, ingreso y egreso del usuario hospitalizado a la unidad de hemodiálisis. IT-JE-40 Admisión, ingreso y egreso del usuario externo a la unidad de hemodiálisis."}, {"no": "5.3", "responsable": "Enfermería", "actividad": "Verifica que el área se encuentre cerrada y evita corrientes de aire."}, {"no": "5.4", "responsable": "Enfermería", "actividad": "Prepara la mesa de trabajo y sanitiza con antiséptico (surfa safe) antes y después de procedimientos, coloca material necesario para realizar procedimiento."}, {"no": "5.5", "responsable": "Enfermería", "actividad": "Realiza lavado de manos."}, {"no": "5.6", "responsable": "Enfermería", "actividad": "Pide al paciente descubrir el sitio donde se encuentra el acceso vascular a manejar e inicia procedimientos."}, {"no": "5.7", "responsable": "Enfermería", "actividad": "Calza un par de guantes crudos para el retiro del apósito que cubre el catéter (sin retirar la gasa que cubre los lúmenes), desprende suavemente y desecha a basura común o a RPBI, según corresponda. No utilizar alcohol para la remoción del apósito previo. PR-JE-08 Manejo de residuos peligrosos biológicos infecciosos."}, {"no": "5.8", "responsable": "Enfermería", "actividad": "Observa datos de infección: enrojecimiento, calor, dolor, secreción purulenta. Si observa datos de infección, registrar y notificar siempre al médico tratante antes de comenzar hemodiálisis."}, {"no": "5.9", "responsable": "Enfermería", "actividad": "Retira guantes crudos y los desecha al tiempo que revisa y observa el sitio de inserción, realiza técnica de higiene de manos con gel o solución alcoholada."}, {"no": "5.10", "responsable": "Enfermería", "actividad": "Abre el equipo de material estéril para curación, únicamente del extremo que contiene el material para la conexión, dejando intacto el extremo con material para desconexión. Abre y deposita en el apartado de conexión las dos jeringas de 20ml y la gasa mediana estéril, sin contaminar."}, {"no": "5.11", "responsable": "Enfermería", "actividad": "Coloca un guante estéril en la mano dominante y prepara el material para realizar curación."}, {"no": "5.12", "responsable": "Enfermería", "actividad": "Vierte tres gasas 7.5 x 5cm de alcohol isopropílico, toma una gasa y realiza asepsia a partir del sitio de inserción del catéter a la periferia en forma circular, en un radio de 7 a 10cm, completando tres tiempos, uno por cada gasa y permite que el alcohol actúe."}, {"no": "5.13", "responsable": "Enfermería", "actividad": "Vierte tres gasas 7.5 x 5cm de antiséptico (Microdacyn), toma una gasa y realiza asepsia a partir del sitio de inserción del catéter a la periferia en forma circular, en un radio de 7 a 10cm, completando tres tiempos y deja actuar el antiséptico."}, {"no": "5.14", "responsable": "Enfermería", "actividad": "Retira el exceso de antiséptico con gasa estéril 7.5 x 5cm seca, deje secar antiséptico y cubre sitio de inserción con dos gasas estériles de 10 x 10 por debajo y encima del lumen, evitando que este tenga contacto con piel y a su vez con el apósito adherible, para después cubrir con apósito hypafix, evitando estirarlo y dejar burbujas."}, {"no": "5.15", "responsable": "Enfermería", "actividad": "Retira gasa que cubre los lúmenes."}, {"no": "5.16", "responsable": "Enfermería", "actividad": "Retira guante y realiza higiene de manos."}, {"no": "5.17", "responsable": "Enfermería", "actividad": "Se coloca un guante del segundo par de guantes estériles."}, {"no": "5.18", "responsable": "Enfermería", "actividad": "Verter alcohol isopropilico en dos gasas estériles 7.5 x 5cm, tomando las extensiones del catéter con una gasa seca con la mano no dominante."}, {"no": "5.19", "responsable": "Enfermería", "actividad": "Coloca el campo estéril en el paciente por debajo de los lúmenes, para aislar las extensiones o lúmenes."}, {"no": "5.20", "responsable": "Enfermería", "actividad": "Se coloca el otro guante."}, {"no": "5.21", "responsable": "Enfermería", "actividad": "Toma una de las gasas con alcohol y limpia de forma rotatoria cada uno de los extremos distales por 60 segundos y retira los tapones, luego, desecha gasa y tapones."}, {"no": "5.22", "responsable": "Enfermería", "actividad": "Toma la segunda gasa impregnada con alcohol y limpia perfectamente la conexión luer lock con fricción por 60 segundos, de manera que se retire cualquier residuo de la conexión anterior."}, {"no": "5.23", "responsable": "Enfermería", "actividad": "Conecta una de las jeringas de 3ml en el puerto arterial, abre clamp, succiona sello de heparina, cierra clamp y desecha la jeringa. Repite con la segunda jeringa en el puerto venoso."}, {"no": "5.24", "responsable": "Enfermería", "actividad": "Toma una jeringa de 20 ml y comprueba la integridad y permeabilidad del lumen arterial y deja conectada al lumen la jeringa. Toma la segunda jeringa de 20 ml y repite la acción con el lumen venoso."}, {"no": "5.25", "responsable": "Enfermería", "actividad": "Observa si existen datos de mal funcionamiento como: disfunción del acceso vascular, bajo flujo o efecto válvula. Notificar al médico y esperar nuevas indicaciones. Si no hay datos de disfunción continuar procedimiento."}, {"no": "5.26", "responsable": "Enfermería", "actividad": "Realiza la conexión firme de los lúmenes a las líneas del circuito extracorpóreo, toma una gasa estéril de 10 x 10cm y envuelve la unión y fija con cinta adherible al paciente y a su vez envuelve con el campo ambos lúmenes fijando con cinta micropore."}, {"no": "5.27", "responsable": "Enfermería", "actividad": "Procede al inicio del tratamiento de hemodiálisis por el tiempo prescrito, y considerando el estado hemodinámico del paciente, al detectar cualquier alteración, notificar de inmediato al médico tratante. IT-JE-26 Intervención de enfermería en el tratamiento de hemodiálisis."}, {"no": "5.28", "responsable": "Enfermería", "actividad": "DESCONEXIÓN: Finalizada la terapia de hemodiálisis, notifica al usuario que se procederá a la desconexión, realiza el retorno sanguíneo del circuito extracorpóreo con solución salina al 0.9% en circuito cerrado y cierra los clamps, verificando que no existan corrientes de aire antes de la desconexión."}, {"no": "5.29", "responsable": "Enfermería", "actividad": "Realiza higiene de manos IT-UV-01 Higiene de manos con agua y jabón, abre el equipo de desconexión estéril, abre dos jeringas de 10ml y las carga con solución salina al 0.9% y abre 2 jeringas de 5 ml y las carga con anticoagulante de acuerdo a la prescripción médica."}, {"no": "5.30", "responsable": "Enfermería", "actividad": "Calza un guante en la mano dominante y vierte en dos gasas de 7.5 x 5cm alcohol isopropilico, con una gasa limpia a modo de fricción en ambas extensiones del catéter, ramales, puntos de unión y líneas, para proceder a desconectar circuito."}, {"no": "5.31", "responsable": "Enfermería", "actividad": "Toma una gasa seca para cubrir las extensiones y protegerlas de ser expuestas al medio ambiente. Con la segunda gasa alcoholada retira cualquier resto hemático de la conexión luer lock."}, {"no": "5.32", "responsable": "Enfermería", "actividad": "Lava cada extensión del catéter con la solución salina de las jeringas de 10ml y aplica la heparina con las jeringas de 5cc según se indique en cada extensión del catéter."}, {"no": "5.33", "responsable": "Enfermería", "actividad": "Pinza inmediatamente clamps, colocando los tapones luer a cada ramal, cubriéndolos con gasa de 10 x 10 estéril."}, {"no": "5.34", "responsable": "Enfermería", "actividad": "Coloca apósito hypafix, sin presionar o estirar sobre la piel, y siendo este apósito uno diferente e independiente al apósito de la parte superior del catéter."}, {"no": "5.35", "responsable": "Enfermería", "actividad": "Realiza higiene de manos con solución alcoholada, se calza guantes crudos y procede a la desinstalación del equipo monitor de hemodiálisis."}, {"no": "5.36", "responsable": "Enfermería", "actividad": "Observaciones: Evitar siempre colocar apósito adherible hypafix sobre extensiones del catéter para reducir adherencias de pegamento, esporas o pelusas. Los mililitros de heparina utilizados son de acuerdo a la prescripción de la extensión de cada lumen del catéter y las unidades, a la indicación médica."}]'::jsonb,
'[{"riesgo": "Acceso vascular con problemas de permeabilidad.", "barrera": "Comprobar permeabilidad de las líneas previo a la conexión. Lavado eficiente de líneas al realizar desconexión. Sellar el catéter con dilución de heparina indicada."}, {"riesgo": "Acceso vascular con datos de infección.", "barrera": "Mantener técnica de barrera máxima al manipular las líneas. Uso de antisépticos adecuados y limpieza eficiente de conectores."}, {"riesgo": "Desconexión accidental de las líneas hemáticas.", "barrera": "Fijación correcta de los lúmenes del catéter durante la sesión de hemodiálisis."}, {"riesgo": "Salida accidental del catéter.", "barrera": "Desprendimiento seguro del apósito. Verificar fijación del catéter a la piel. No dejar traccionada la línea del catéter durante la sesión."}]'::jsonb,
'[{"nombre": "Secretaria de salud (2018) Manual para el cuidado estandarizado de enfermería a la persona con acceso vascular para hemodiálisis", "codigo": "No aplica"}, {"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}, {"nombre": "Manejo de medidas precautorias", "codigo": "IT-JE-18"}, {"nombre": "Intervención de enfermería en el tratamiento de hemodiálisis", "codigo": "IT-JE-26"}, {"nombre": "Admisión, ingreso y egreso del usuario hospitalizado a la unidad de hemodiálisis", "codigo": "IT-JE-39"}, {"nombre": "Admisión, ingreso y egreso del usuario externo a la unidad de hemodiálisis", "codigo": "IT-JE-40"}, {"nombre": "Manejo de residuos peligrosos biológicos infecciosos", "codigo": "PR-JE-08"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
FROM documents d WHERE d.code = 'IT-JE-20'
ON CONFLICT (document_id) DO UPDATE SET
  objetivo            = EXCLUDED.objetivo,
  alcance             = EXCLUDED.alcance,
  material_equipo     = EXCLUDED.material_equipo,
  desarrollo          = EXCLUDED.desarrollo,
  gestion_riesgos     = EXCLUDED.gestion_riesgos,
  referencias         = EXCLUDED.referencias,
  control_cambios     = EXCLUDED.control_cambios,
  elaborado_por       = EXCLUDED.elaborado_por,
  cargo_elaboro       = EXCLUDED.cargo_elaboro,
  revisado_por        = EXCLUDED.revisado_por,
  cargo_reviso        = EXCLUDED.cargo_reviso,
  autorizado_por      = EXCLUDED.autorizado_por,
  cargo_autorizo      = EXCLUDED.cargo_autorizo;

