SELECT d.id,
'Inicia en el momento que finaliza sesión de hemodiálisis del paciente y termina al dejar la máquina lista para la conexión de nuevas líneas.',
'Inicia en el momento que finaliza sesión de hemodiálisis del paciente y termina al dejar la máquina lista para la conexión de nuevas líneas.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "SURFA-SAFE"}, {"item": "Franela morada"}, {"item": "Compresa o gasa"}, {"item": "Cubrebocas"}, {"item": "Guante crudo"}, {"item": "Bote de RPBI"}, {"item": "Bote de basura común"}]'::jsonb,
'[{"no": "5.1", "responsable": "Enfermería", "actividad": "Terminada la sesión de hemodiálisis y egresado el paciente inicia con la limpieza de la máquina."}, {"no": "5.2", "responsable": "Enfermería", "actividad": "Realiza higiene de manos IT-UV-01 Higiene de manos con agua y jabón y retira el circuito de la máquina de hemodiálisis y lo desecha. PR-JE-08 Manejo de RPBI."}, {"no": "5.3", "responsable": "Enfermería", "actividad": "Regresa la lanceta colocada en el bidón del potasio a su lugar y se desmonta el bibag, se asegura de cerrar bien la ventana."}, {"no": "5.4", "responsable": "Enfermería", "actividad": "Presiona el botón de desinfección, posterior a asegurarse que la máquina está desmontada. (el proceso de la máquina dura 16 minutos)."}, {"no": "5.5", "responsable": "Enfermería", "actividad": "Procede a realizar una limpieza y desinfección de la máquina de manera manual con surfa-safe y franela morada (mientras se realiza el proceso de desinfección)."}, {"no": "5.6", "responsable": "Enfermería", "actividad": "Retirar con gasa o compresa impregnada con surfa-safe, los derrames de contenido hemático."}, {"no": "5.7", "responsable": "Enfermería", "actividad": "Solicita a jefatura de enfermería SURFASAFE y la franela morada."}, {"no": "5.8", "responsable": "Enfermería", "actividad": "Respeta el tiempo de desinfección entre sesiones."}, {"no": "5.9", "responsable": "Enfermería", "actividad": "Al terminar la desinfección, la máquina esta lista para realizar el montaje de la nueva sesión. Realiza higiene de manos IT-UV-01 Higiene de manos con agua y jabón."}]'::jsonb,
'[{"riesgo": "SURFASAFE o franela insuficiente o en mal estado.", "barrera": "Solicitud con antelación de insumos a jefatura de enfermería."}, {"riesgo": "Proceso de limpieza omitido por parte del personal.", "barrera": "Respetar las horas de programación y el tiempo de desinfección entre sesiones."}]'::jsonb,
'[{"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}, {"nombre": "Manejo de RPBI", "codigo": "PR-JE-08"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
