-- ── IT-JE-26 ─────────────────────────────────────────────────────
INSERT INTO document_content (
  document_id, objetivo, alcance,
  definiciones, responsabilidades, material_equipo, desarrollo,
  gestion_riesgos, referencias, control_cambios,
  elaborado_por, cargo_elaboro,
  revisado_por,  cargo_reviso,
  autorizado_por, cargo_autorizo
)
SELECT d.id,
'Inicia con la revisión de la programación y la preparación de la máquina para la sesión, termina con la finalización de los registros de enfermería y la desinfección del reposet.',
'Inicia con la revisión de la programación y la preparación de la máquina para la sesión, termina con la finalización de los registros de enfermería y la desinfección del reposet.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "Mesa de trabajo"}, {"item": "Sanitizante SURFA-SAFE"}, {"item": "Toalla o sanita"}, {"item": "Guante crudo (2pzas)"}, {"item": "Guante estéril (2pzas)"}, {"item": "Jeringa de 20ml"}, {"item": "Heparina 5000UI"}, {"item": "Circuito"}, {"item": "Filtro"}, {"item": "Bibag"}, {"item": "Máquina de hemodiálisis"}, {"item": "Báscula"}, {"item": "Estetoscopio"}, {"item": "Baumanómetro manual"}, {"item": "Termómetro"}, {"item": "Oxisensor de pulso"}]'::jsonb,
'[{"no": "5.1", "responsable": "Enfermería", "actividad": "Revisa bitácora de programación de sesión de hemodiálisis."}, {"no": "5.2", "responsable": "Enfermería", "actividad": "Antes de entrar en contacto con el paciente y su entorno, realizar lavado de manos clínico. IT-UV-01 Higiene de manos. Y portar adecuadamente las medidas precautorias para el manejo del usuario. IT-JE-18 Manejo de medidas precautorias para el personal de hemodiálisis."}, {"no": "5.3", "responsable": "Enfermería", "actividad": "Realiza la preparación de la máquina previa sesión de paciente."}, {"no": "5.4", "responsable": "Enfermería", "actividad": "Coloca el circuito de manera correcta y coloca el filtro (calibre según indicado por el médico)."}, {"no": "5.5", "responsable": "Enfermería", "actividad": "Coloca el bidón de potasio con su lanceta y el bibag en su lugar correcto."}, {"no": "5.6", "responsable": "Enfermería", "actividad": "Realiza un test para que la máquina verifique posibles fallas en el sistema para evitar riesgos al paciente durante la sesión."}, {"no": "5.7", "responsable": "Enfermería", "actividad": "Realiza cebado del circuito mientras se realiza el test, para sacar todo el aire y evitar complicaciones en el paciente."}, {"no": "5.8", "responsable": "Enfermería", "actividad": "Conecta la línea arterial a la venosa del circuito (al terminar el test) para realizar una recirculación de solución para retirar posibles burbujas de aire que se pueden alojar en el filtro."}, {"no": "5.9", "responsable": "Enfermería", "actividad": "Deja la bomba de la máquina en 0 y apaga el flujo para no consumir el bidón del potasio antes de iniciar sesión."}, {"no": "5.10", "responsable": "Enfermería", "actividad": "Recibe paciente al llegar a sesión de hemodiálisis, revisa indicaciones médicas, verificando que estén vigentes y detecta si hay indicación de toma de muestras de sangre, pesa al paciente y lo instala en la máquina asignada para su procedimiento."}, {"no": "5.11", "responsable": "Enfermería", "actividad": "Realiza la conexión de monitor de hemodiálisis, para valorar constantes vitales."}, {"no": "5.12", "responsable": "Enfermería", "actividad": "Programa datos en máquina de hemodiálisis del tratamiento requerido, tomando en cuenta los siguientes tres factores: indicación médica, valoración previa del usuario y laboratoriales."}, {"no": "5.13", "responsable": "Enfermería", "actividad": "Carga en la jeringa de 20ml 1cc del frasco de heparina de 5000UI y afora con solución salina al 0.9% a 10ml o 20ml según factibilidad de unidades a infundir, coloca jeringa en elevador inyector del monitor y programa mililitros por hora según lo indicado."}, {"no": "5.14", "responsable": "Enfermería", "actividad": "Notifica vía telefónica a médico tratante en caso de eventualidad en el estado general del paciente y espera indicaciones nuevas."}, {"no": "5.15", "responsable": "Enfermería", "actividad": "Sanitiza la mesa de trabajo con el desinfectante establecido en el protocolo de la institución y procede a preparar el material de conexión de acuerdo al acceso vascular a manejar y realiza actividades de conexión. IT-JE-21 Manejo y cuidado del acceso vascular para hemodiálisis FAVI o IT-JE-20 Manejo y cuidado del acceso vascular para hemodiálisis catéter."}, {"no": "5.16", "responsable": "Enfermería", "actividad": "Toma muestras de sangre para laboratorio previo al inicio de la sesión (solo cuando estén indicados)."}, {"no": "5.17", "responsable": "Enfermería", "actividad": "Verifica seguridad y comodidad del usuario, asegurando el resguardo y firmeza de líneas del circuito extracorpóreo para evitar eventos adversos/centinela."}, {"no": "5.18", "responsable": "Enfermería", "actividad": "Realiza toma de constantes vitales dando inicio al tratamiento y realiza los registros correspondientes en la hoja de enfermería."}, {"no": "5.19", "responsable": "Enfermería", "actividad": "Administra bolo de heparina al inicio del tratamiento, solo en caso de estar indicado; y ajusta flujo sanguíneo en bomba de sangre, según lo indicado."}, {"no": "5.20", "responsable": "Enfermería", "actividad": "Realiza técnica de lavado de manos IT-UV-01 Higiene de manos con agua y jabón posterior a manipulaciones con el usuario, su entorno y accesorios, como máquina monitor."}, {"no": "5.21", "responsable": "Enfermería", "actividad": "Realiza registro de constantes vitales de manera periódica durante tratamiento según estado general del usuario, llevando control de registro de cifras y horario."}, {"no": "5.22", "responsable": "Enfermería", "actividad": "Valora constantemente el estado general de usuario, mediante observación directa, interrogación al usuario y vigilancia de signos vitales, en búsqueda de alteraciones hemodinámicas."}, {"no": "5.23", "responsable": "Enfermería", "actividad": "Notifica a médico en caso de observar signos o síntomas de alarma y comienza manejo de acuerdo a indicación y protocolo."}, {"no": "5.24", "responsable": "Enfermería", "actividad": "Administra medicamentos cumpliendo con los correctos en la administración de medicamentos y según indicación médica."}, {"no": "5.25", "responsable": "Enfermería", "actividad": "Prepara medicamentos sobre mesa de trabajo desinfectada, cuidando manejo aséptico de frascos y materiales, diluye medicamentos de acuerdo a indicación médica."}, {"no": "5.26", "responsable": "Enfermería", "actividad": "Manejo de técnica aséptica en todo momento al conectar, desconectar, administrar medicamentos o hemocomponentes para evitar contaminación."}, {"no": "5.27", "responsable": "Enfermería", "actividad": "Conecta en lumen de cámara venosa jeringa o fleboteck con dilución medicamentosa indicada. Inyecta de manera manual o programa bomba de infusión, de acuerdo al fármaco administrado. IT-JE-28 Administración de Medicamentos vía intravenosa."}, {"no": "5.28", "responsable": "Enfermería", "actividad": "Una vez finalizada farmacoterapia, retira jeringas, fleboteck utilizado y desecha PR-JE-08 Manejo de RPBI, cuidando pinzar lúmenes antes del retiro, y coloca tapones luer."}, {"no": "5.29", "responsable": "Enfermería", "actividad": "Sanitiza mesa de trabajo y prepara material de desconexión de acuerdo al acceso vascular manejado. IT-JE-21 Manejo y cuidado del acceso vascular para hemodiálisis FAVI y IT-JE-20 Manejo y cuidado del acceso vascular para hemodiálisis catéter."}, {"no": "5.30", "responsable": "Enfermería", "actividad": "Toma constantes vitales finales en últimos minutos del tratamiento y nuevamente al finalizar el retorno sanguíneo, procediendo a desconexión, desechando equipo extracorpóreo."}, {"no": "5.31", "responsable": "Enfermería", "actividad": "Vigila datos de sangrado durante la sesión y posterior a hemostasia en pacientes con FAVI o injerto."}, {"no": "5.32", "responsable": "Enfermería", "actividad": "Realiza registro de constantes vitales y parámetros finales del tratamiento, completa reporte de enfermería, con su nombre, firma y cédula."}, {"no": "5.33", "responsable": "Enfermería", "actividad": "Da egreso al usuario ambulatorio u hospitalizado en coordinación con administración, camillería o enfermería de hospitalización (según corresponda)."}, {"no": "5.34", "responsable": "Enfermería", "actividad": "Realiza limpieza de máquina de hemodiálisis con SURFA-SAFE y franela morada, retira sangre derramada en la máquina con ayuda de gasas crudas o toallas de papel. IT-JE-22 Técnica de sanitización de la máquina de hemodiálisis. Realiza limpieza de camilla y reposet con franela verde y dilución de cloro al 1% cuando se considere contaminado y al 0.1% cuando se considere no contaminado."}, {"no": "5.35", "responsable": "Enfermería", "actividad": "Observaciones: La indicación médica debe estar actualizada mensualmente en caso de usuario externo, o diariamente en caso de usuario hospitalizado. La valoración previa al inicio del usuario, se realizará con la toma de signos vitales, interrogatorio y observación de presencia de edema, realizada por enfermería. El colaborador debe desarrollar las habilidades clínicas pertinentes que le apoyen en la observación de cambios hemodinámicos de importancia del usuario. El reporte de enfermería debe realizarse en tiempo y forma mientras el tratamiento transcurre, llenándose con los datos del colaborador que realiza, con máximo dos colaboradores si el paciente inició y finalizó en distintos turnos."}]'::jsonb,
'[{"riesgo": "Muestras de sangre no tomadas de manera oportuna.", "barrera": "Revisar las indicaciones médicas previo al inicio de la sesión, buscando de manera intencionada la toma de muestras."}, {"riesgo": "Circuito con burbujas de aire por purgado inadecuado.", "barrera": "Realizar cebado de la máquina de hemodiálisis durante la realización del test. Realizar recirculación en el mismo circuito, para detectar y extraer burbujas del circuito y filtro."}, {"riesgo": "Paciente complicado por infección adquirida durante la atención recibida.", "barrera": "Realizar higiene de manos respetando los 5 momentos. Apego a protocolos de desinfección de mesa de trabajo, máquina de hemodiálisis y reposet."}]'::jsonb,
'[{"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}, {"nombre": "Manejo de RPBI", "codigo": "PR-JE-08"}, {"nombre": "Manejo de medidas precautorias para el personal de hemodiálisis", "codigo": "IT-JE-18"}, {"nombre": "Manejo y cuidado del acceso vascular para hemodiálisis FAVI", "codigo": "IT-JE-21"}, {"nombre": "Manejo y cuidado del acceso vascular para hemodiálisis catéter", "codigo": "IT-JE-20"}, {"nombre": "Administración de Medicamentos vía intravenosa", "codigo": "IT-JE-28"}, {"nombre": "Instrucción de trabajo para la técnica de sanitización de la máquina de hemodiálisis", "codigo": "IT-JE-22"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
