SELECT d.id,
'Inicia con la indicación médica de sesión de hemodiálisis, continua en el área de hemodiálisis al realizar sesión y finaliza al salir el paciente de la unidad.',
'Inicia con la indicación médica de sesión de hemodiálisis, continua en el área de hemodiálisis al realizar sesión y finaliza al salir el paciente de la unidad.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "Silla de ruedas"}, {"item": "Camilla hospitalaria"}, {"item": "Gorro desechable"}, {"item": "Cubre boca desechable"}, {"item": "Silla reposet reclinable"}, {"item": "Consentimiento informado"}, {"item": "Báscula con rampa"}, {"item": "Baumanómetro y estetoscopio"}, {"item": "Termómetro"}, {"item": "Oxímetro"}, {"item": "Tanque de oxigeno"}, {"item": "Máquina de hemodiálisis"}]'::jsonb,
'[{"no": "5.1", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Lee y corrobora en la indicación médica la solicitud del tratamiento de hemodiálisis para el paciente hospitalizado y notifica al personal de enfermería de la unidad de hemodiálisis."}, {"no": "5.2", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Solicita fecha y horario de sesión, e informa requerimientos de oxígeno, succión, bomba de infusión, si es trasladado en silla o camilla, y el estado del paciente. PR-JE-02 MISP 2. Mejorar la comunicación efectiva."}, {"no": "5.3", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Recibe solicitud para programar paciente de piso a la unidad de hemodiálisis, valora cumplimiento de requisitos para la admisión al área."}, {"no": "5.4", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Revisa programación y asigna hora y fecha de sesión. En caso de ser urgente, busca la sesión más próxima."}, {"no": "5.5", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Prepara unidad de hemodiálisis para recibir paciente de piso de acuerdo a las necesidades del paciente."}, {"no": "5.6", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Se comunica y solicita a personal de enfermería de atención en piso para trasladar al usuario a unidad de hemodiálisis en turno programado."}, {"no": "5.6b", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Brindar los cuidados generales al paciente, como vaciado de drenajes y sondas, administración de fármacos o hemoderivados específicos indicados pre hemodiálisis por médico especialista."}, {"no": "5.6c", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Solicita el traslado del paciente a la unidad de hemodiálisis al servicio de camillería, de ser necesario lo programa con anticipación."}, {"no": "5.7", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Realizar IT-UV-01 Higiene de manos, y realizar IT-JE-18 Manejo de medidas precautorias para el personal de hemodiálisis."}, {"no": "5.8", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Recibe al paciente acompañado por el personal de enfermería de piso, con expediente clínico corrobora indicación, así como datos generales y de identificación."}, {"no": "5.8b", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Entrega expediente y paciente en el servicio de hemodiálisis, informa estado hemodinámico y neurológico, indicación médica, farmacoterapia, soluciones e infusiones, catéteres o sondas y cuidados generales."}, {"no": "5.8c", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Prepara la cama y se mantiene alerta para recibir paciente al finalizar procedimiento."}, {"no": "5.8d", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Realiza manejo de IT-JE-18 Manejo de medidas precautorias para el personal de hemodiálisis."}, {"no": "5.8e", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Realiza monitoreo de signos vitales pre-hemodiálisis y registra en hoja de enfermería en hemodiálisis: Peso seco (en caso de conocerlo), Peso al ingreso, Presión arterial, Frecuencia cardiaca, Temperatura corporal, Frecuencia respiratoria, Saturación de oxigeno."}, {"no": "5.8f", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Al detectar alguna alteración hemodinámica informar a médico tratante y esperar indicaciones."}, {"no": "5.8g", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Inicia tratamiento de hemodiálisis. IT-JE-26 Intervención de enfermería en el tratamiento de hemodiálisis. IT-JE-20 Manejo y cuidado de acceso vascular para hemodiálisis - catéter. IT-JE-21 Manejo y cuidado de acceso vascular para hemodiálisis - FAVI."}, {"no": "5.8h", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Finalizado el tratamiento, si el usuario está en reposet, lo coloca en posición sentado, elevando respaldo y bajando miembros inferiores. Si el usuario se encuentra en camilla, solo se da posición preferente y segura. De ser posible pesa al paciente al finalizar la sesión."}, {"no": "5.8i", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Comunica al enfermero de atención en piso que la sesión de hemodiálisis ha finalizado para solicitar el traslado a habitación, al tiempo que solicita el apoyo de camillero."}, {"no": "5.8j", "responsable": "Personal de Enfermería Hemodiálisis", "actividad": "Realiza la entrega de paciente, mencionando estado general, transfusión o farmacoterapia durante la sesión de hemodiálisis."}, {"no": "5.9", "responsable": "Personal de Enfermería Atención en piso", "actividad": "Al finalizar procedimiento recibe paciente en la unidad de hemodiálisis, valora estado general, lo acompaña a su habitación y lo instala."}]'::jsonb,
'[{"riesgo": "Sesión de hemodiálisis retrasada por envío tardío del paciente.", "barrera": "Brindar los cuidados de enfermería prehemodiálisis por enfermera de piso con tiempo suficiente antes de la sesión. Solicitar a camillería el traslado oportuno del paciente."}, {"riesgo": "Infección adquirida por arrastre de microorganismos.", "barrera": "Cumplir con higiene de manos respetando los 5 momentos. Cumplir con los protocolos para ingreso y egreso del área."}, {"riesgo": "Paciente con inestabilidad hemodinámica.", "barrera": "Monitorizar signos vitales del paciente y estado del paciente."}]'::jsonb,
'[{"nombre": "Manejo de medidas precautorias para el personal de hemodiálisis", "codigo": "IT-JE-18"}, {"nombre": "Manejo y cuidado de acceso vascular para hemodiálisis - catéter", "codigo": "IT-JE-20"}, {"nombre": "Manejo y cuidado de acceso vascular para hemodiálisis - FAVI", "codigo": "IT-JE-21"}, {"nombre": "Intervención de enfermería en el tratamiento de hemodiálisis", "codigo": "IT-JE-26"}, {"nombre": "MISP 2. Mejorar la comunicación efectiva", "codigo": "PR-JE-02"}, {"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
FROM documents d WHERE d.code = 'IT-JE-39'
