SELECT d.id,
'Inicia al tener preparado el medicamento, continua durante la administración, registro, y termina al concluir administración y retirarse de la habitación y realizar el registro correspondiente.',
'Inicia al tener preparado el medicamento, continua durante la administración, registro, y termina al concluir administración y retirarse de la habitación y realizar el registro correspondiente.',
'[]'::jsonb,
'[]'::jsonb,
'[{"item": "Medicamento"}, {"item": "Jeringa"}, {"item": "Aguja"}, {"item": "Gasa estéril"}, {"item": "Solución salina al 0.9%"}, {"item": "Agua inyectable"}, {"item": "Toma de oxigeno"}, {"item": "Mascarilla micronebulizador"}, {"item": "Micronebulizador con tubo en T"}, {"item": "Nebulizador en malla (Aerogen)"}]'::jsonb,
'[{"no": "5.1", "responsable": "Terapia respiratoria", "actividad": "Inicia posterior a preparar y rotular el medicamento. IT-JE-42 Instrucción de trabajo preparación de medicamentos nebulizados."}, {"no": "5.2", "responsable": "Terapia respiratoria", "actividad": "Reúne material, equipo y medicamento requerido y corrobora indicación médica."}, {"no": "5.3", "responsable": "Terapia respiratoria", "actividad": "Realiza lavado de manos. IT-UV-01 Higiene de manos con agua y jabón."}, {"no": "5.4", "responsable": "Terapia respiratoria", "actividad": "Se dirige a habitación con el material y medicamento e identifica al paciente. PR-JE-01 Identificación correcta del paciente."}, {"no": "5.5", "responsable": "Terapia respiratoria", "actividad": "Se presenta y explica procedimiento a seguir a paciente y familiar, aclara dudas."}, {"no": "5.6", "responsable": "Terapia respiratoria", "actividad": "Valora patrón respiratorio del paciente, saturación, frecuencia respiratoria, profundidad, ruidos respiratorios, etc."}, {"no": "5.7", "responsable": "Terapia respiratoria", "actividad": "Coloca al paciente en posición cómoda y adecuada, de preferencia semifowler."}, {"no": "5.8", "responsable": "Terapia respiratoria", "actividad": "Conecta flujometro a la toma de oxígeno y verifica su funcionalidad."}, {"no": "5.9", "responsable": "Terapia respiratoria", "actividad": "Valora la integridad de los equipos a utilizar. Cuida que ninguna pieza caiga al suelo, ni se contamine. Conecta al flujometro el conector niple y la mascarilla con el micronebulizador. En circuito conecta el micronebulizador con conector en T. En caso de estar indicado, se hará uso del aerogen."}, {"no": "5.10", "responsable": "Terapia respiratoria", "actividad": "Vierte el medicamento previamente preparado en la cazoleta del nebulizador."}, {"no": "5.11", "responsable": "Terapia respiratoria", "actividad": "Abre el flujometro en los litros que sea necesario y verifica su funcionamiento. Accionar la nebulización en la pantalla del ventilador."}, {"no": "5.12", "responsable": "Terapia respiratoria", "actividad": "Coloca el dispositivo y lo ajusta a la medida del paciente, asegurándose quede vertical y no se derrame el medicamento."}, {"no": "5.13", "responsable": "Terapia respiratoria", "actividad": "Recomienda al paciente realizar respiraciones profundas y lentas, cuando el paciente pueda realizarlas."}, {"no": "5.14", "responsable": "Terapia respiratoria", "actividad": "Valora la tolerancia a la medicación."}, {"no": "5.15", "responsable": "Terapia respiratoria", "actividad": "Realiza el procedimiento durante 10 minutos aproximadamente, o hasta el término del medicamento."}, {"no": "5.16", "responsable": "Terapia respiratoria", "actividad": "Al término de la nebulización cierra el flujometro y retira el equipo (de requerirlo realiza la limpieza de este) y lo coloca en una bolsa, lo deja en la unidad del paciente para continuar con el tratamiento las veces que sea indicado."}, {"no": "5.17", "responsable": "Terapia respiratoria", "actividad": "En caso de requerir oxígeno suplementario, colocar el equipo indicado."}, {"no": "5.18", "responsable": "Terapia respiratoria", "actividad": "Deja cómodo al paciente y se retira de la habitación."}, {"no": "5.19", "responsable": "Terapia respiratoria", "actividad": "Realiza higiene de manos y los registros pertinentes."}]'::jsonb,
'[{"riesgo": "Mucosa lesionada por mala ejecución de la administración.", "barrera": "Regular el flujo de oxígeno necesario para hacer efectiva la nebulización. Si el paciente se mantiene con oxígeno suplementario, regular el flujo al terminar la nebulización."}, {"riesgo": "Medicamento administrado a paciente incorrecto.", "barrera": "Colocar etiqueta a los medicamentos al prepararlos. Aplicar los 10 correctos en la administración de medicamentos. Identificar al paciente previo a la administración."}]'::jsonb,
'[{"nombre": "MISP.1 Identificar correctamente a los pacientes", "codigo": "PR-JE-01"}, {"nombre": "Higiene de manos con agua y jabón", "codigo": "IT-UV-01"}, {"nombre": "Preparación de medicamentos nebulizados", "codigo": "IT-JE-42"}]'::jsonb,
'[{"version": "01", "fecha": "Julio 2021", "descripcion": "Alta de documento", "realizado": "Toledo Casas Gerardo", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "Agosto 2024", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "Septiembre 2025", "descripcion": "Actualización de documento", "realizado": "Mendoza Garcia Mayda Guadalupe", "aprobado": "Juan Carlos Vanegas Reyes"}]'::jsonb,
'Lic. Juan Carlos Vanegas Reyes', 'Jefatura de enfermería',
'Dra. Giselle Ivette De la Torre García',  'Jefatura de Calidad',
'Hna. María de Jesús García Castro', 'Dirección General'
FROM documents d WHERE d.code = 'IT-JE-41'
