SELECT d.id,
'Inicia con la recepción y conteo de ropa limpia, en uso y en vale, continua durante el destendido de cama o camilla y la clasificación de ropa sucia, termina en el conteo de ropa limpia, sucia y en vale.',
'Inicia con la recepción y conteo de ropa limpia, en uso y en vale, continua durante el destendido de cama o camilla y la clasificación de ropa sucia, termina en el conteo de ropa limpia, sucia y en vale.',
'[]'::jsonb,
'[]'::jsonb,
